func sendToAll(r *Replica, msg fastrpc.Serializable, rpc uint8) {
	for p := int32(0); p < int32(r.N); p++ {
		r.M.Lock()
		if r.Alive[p] {
			r.M.Unlock()
			r.SendMsg(p, rpc, msg)
			r.M.Lock()
		}
		r.M.Unlock()
	}
}

func sendToAllExcept(r *Replica, except int32, msg fastrpc.Serializable, rpc uint8) {
	for p := int32(0); p < int32(r.N); p++ {
		if p == except {
			continue
		}
		r.M.Lock()
		if r.Alive[p] {
			r.M.Unlock()
			r.SendMsg(p, rpc, msg)
			r.M.Lock()
		}
		r.M.Unlock()
	}
}

func sendToQuorum(r *Replica, q Quorum,
	msg fastrpc.Serializable, rpc uint8) {
	for p := int32(0); p < int32(r.N); p++ {
		if !q.Contains(p) {
			continue
		}
		r.M.Lock()
		if r.Alive[p] {
			r.M.Unlock()
			r.SendMsg(p, rpc, msg)
			r.M.Lock()
		}
		r.M.Unlock()
	}
}

func sendExcept(r *Replica, q Quorum,
	msg fastrpc.Serializable, rpc uint8) {
	for p := int32(0); p < int32(r.N); p++ {
		if q.Contains(p) {
			continue
		}
		r.M.Lock()
		if r.Alive[p] {
			r.M.Unlock()
			r.SendMsg(p, rpc, msg)
			r.M.Lock()
		}
		r.M.Unlock()
	}
}
package replica

type MsgSetHandler func(interface{}, []interface{})

type MsgSet struct {
	q         QuorumI
	msgs      map[int32]interface{}
	leaderMsg interface{}
	accept    func(interface{}, interface{}) bool
	freeMsg   func(interface{})
	handler   MsgSetHandler
}

func NewMsgSet(q QuorumI, accept func(interface{}, interface{}) bool,
	freeMsg func(interface{}), handler MsgSetHandler) *MsgSet {

	return &MsgSet{
		q:         q,
		msgs:      map[int32]interface{}{},
		leaderMsg: nil,
		accept:    accept,
		freeMsg:   freeMsg,
		handler:   handler,
	}
}

func (ms *MsgSet) ReinitMsgSet(q QuorumI, accept func(interface{}, interface{}) bool,
	freeMsg func(interface{}), handler MsgSetHandler) *MsgSet {

	if ms == nil {
		return NewMsgSet(q, accept, freeMsg, handler)
	}

	ms.q = q
	ms.leaderMsg = nil
	ms.accept = accept
	ms.freeMsg = freeMsg
	ms.handler = handler
	for rep := range ms.msgs {
		delete(ms.msgs, rep)
	}
	return ms
}

func (ms *MsgSet) Add(repId int32, isLeader bool, msg interface{}) bool {
	if !ms.q.Contains(repId) {
		return false
	}

	if _, seen := ms.msgs[repId]; ms.leaderMsg != nil && seen {
		return false
	}

	added := false

	if isLeader {
		ms.leaderMsg = msg
		newMsgs := map[int32]interface{}{}
		for frepId, fmsg := range ms.msgs {
			if _, seen := newMsgs[frepId]; !seen && ms.accept(fmsg, ms.leaderMsg) {
				newMsgs[frepId] = fmsg
			} else {
				ms.freeMsg(fmsg)
			}
		}
		ms.msgs = newMsgs
		added = true
	} else if ms.accept(msg, ms.leaderMsg) {
		ms.msgs[repId] = msg
		added = true
	} else {
		ms.freeMsg(msg)
	}

	if len(ms.msgs) >= ms.q.Size() ||
		(len(ms.msgs) >= ms.q.Size()-1 && ms.leaderMsg != nil) {
		m := make([]interface{}, len(ms.msgs))
		i := 0
		for _, v := range ms.msgs {
			m[i] = v
			i++
		}
		ms.handler(ms.leaderMsg, m)
	}

	return added
}

func (ms *MsgSet) Free() {
	if ms == nil {
		return
	}
	if ms.leaderMsg != nil {
		ms.freeMsg(ms.leaderMsg)
	}
	for _, fmsg := range ms.msgs {
		if fmsg != nil {
			ms.freeMsg(fmsg)
		}
	}
}

